
CREATE TABLE public.batalhas_agendadas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, artista1_nome text NOT NULL DEFAULT '', artista1_musica text NOT NULL DEFAULT '', artista1_porcentagem integer NOT NULL DEFAULT 0, artista1_imagem text NOT NULL DEFAULT '', artista2_nome text NOT NULL DEFAULT '', artista2_musica text NOT NULL DEFAULT '', artista2_porcentagem integer NOT NULL DEFAULT 0, artista2_imagem text NOT NULL DEFAULT '', data_batalha date NOT NULL, horario_inicio text NOT NULL, horario_fim text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.blitz_promocionais (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, dia date NOT NULL, horario time NOT NULL, cliente text NOT NULL, equipe text, observacoes text, realizada boolean NOT NULL DEFAULT false, data_realizacao timestamptz, horario_fim time, agenda_evento_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.blitz_promocionais_historico (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, blitz_id uuid, cliente text, acao text NOT NULL, motivo text, dados_antes jsonb, dados_depois jsonb, changed_by uuid, changed_by_email text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.broadcast_assuntos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, programa_id uuid NOT NULL, mensagens jsonb NOT NULL DEFAULT '[]'::jsonb, font_family text NOT NULL DEFAULT 'Inter', mensagens_enabled boolean[] NOT NULL DEFAULT '{}', rotation_seconds integer NOT NULL DEFAULT 10, bg_color text NOT NULL DEFAULT '#000000', text_color text NOT NULL DEFAULT '#ffffff', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,programa_id));
CREATE TABLE public.cenario_estudio_web (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, nome text NOT NULL DEFAULT 'Novo cenário web', orientation text NOT NULL DEFAULT 'horizontal', tv_count integer NOT NULL DEFAULT 1, content jsonb NOT NULL DEFAULT '{"gradient":true,"presenter":true,"artist":true,"sponsors":true}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.client_actions_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, client_id uuid NOT NULL, action_type text NOT NULL, description text, metadata jsonb DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.client_trash (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE, email text, nome text, deleted_by uuid, deleted_at timestamptz NOT NULL DEFAULT now(), purge_at timestamptz NOT NULL DEFAULT (now()+interval '60 days'), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.comercial_mockups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, image_url text, fields jsonb DEFAULT '[]'::jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE public.comercial_propostas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, mockup_id uuid REFERENCES public.comercial_mockups(id) ON DELETE SET NULL, title text NOT NULL, data jsonb DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'rascunho', final_art_url text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE public.custom_enquete_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, nome text NOT NULL, quizzes jsonb NOT NULL DEFAULT '[]'::jsonb, generated_date date NOT NULL DEFAULT CURRENT_DATE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.custom_quiz_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, nome text NOT NULL, quizzes jsonb NOT NULL DEFAULT '[]'::jsonb, generated_date date NOT NULL DEFAULT CURRENT_DATE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.enquetes_agendadas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, pergunta text NOT NULL DEFAULT '', resposta1 text NOT NULL DEFAULT '', resposta2 text NOT NULL DEFAULT '', resposta3 text NOT NULL DEFAULT '', resposta4 text NOT NULL DEFAULT '', resposta_correta integer NOT NULL DEFAULT 1, data_enquete date NOT NULL, horario_inicio text NOT NULL, horario_fim text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.google_calendar_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE, access_token text NOT NULL, refresh_token text NOT NULL, token_expiry timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.infomusic (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), artista text NOT NULL, musica text NOT NULL, curiosidade text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now()+interval '30 days'));
CREATE TABLE public.infomusic_excecoes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, termo text NOT NULL, capa_url text, background_url text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), UNIQUE(user_id,termo));
CREATE TABLE public.music_likes_youtube_cache (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, artista text NOT NULL, titulo text NOT NULL, video_id text NOT NULL, thumbnail text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,artista,titulo));
CREATE TABLE public.musicas_tocadas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, dia date NOT NULL DEFAULT CURRENT_DATE, horario time NOT NULL DEFAULT CURRENT_TIME, programa text NOT NULL DEFAULT '', artista text NOT NULL DEFAULT '', musica text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.news_cache (site_id uuid PRIMARY KEY REFERENCES public.custom_news_sites(id) ON DELETE CASCADE, user_id uuid NOT NULL, items jsonb NOT NULL DEFAULT '[]'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), last_error text);
CREATE TABLE public.planos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, image_url text DEFAULT '', enabled_modules text[] DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.player_heartbeats (session_id text PRIMARY KEY, master_user_id uuid NOT NULL, last_seen timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.player_listener_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), auth_user_id uuid NOT NULL, radio_user_id uuid NOT NULL, nome text, email text, cidade text, estado text, whatsapp text, sexo text, avatar_url text, cpf text, data_nascimento date, setor text, sub_profiles jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(auth_user_id,radio_user_id));
CREATE TABLE public.preset_commands (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, programa_id uuid NOT NULL, commands jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,programa_id));
CREATE TABLE public.programa_automacoes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, programa_id uuid NOT NULL REFERENCES public.programas(id) ON DELETE CASCADE, sites_source text[] NOT NULL DEFAULT '{}', use_custom_news_sites boolean NOT NULL DEFAULT true, briefing text NOT NULL DEFAULT '', dias_semana text[] NOT NULL DEFAULT '{}', horario text NOT NULL DEFAULT '08:00', ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.prompt_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL, content text NOT NULL, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE public.quiz_agendados (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, pergunta text NOT NULL DEFAULT '', resposta1 text NOT NULL DEFAULT '', resposta2 text NOT NULL DEFAULT '', resposta3 text NOT NULL DEFAULT '', resposta4 text NOT NULL DEFAULT '', resposta_correta integer NOT NULL DEFAULT 1, data_quiz date NOT NULL, horario_inicio text NOT NULL, horario_fim text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.roteiros (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, programa_nome text NOT NULL DEFAULT '', estudio text NOT NULL DEFAULT '', tipo_programa text NOT NULL DEFAULT '', data_programa date NOT NULL DEFAULT CURRENT_DATE, horario text NOT NULL DEFAULT '', titulo text NOT NULL DEFAULT '', subtitulo text NOT NULL DEFAULT '', conteudo_html text NOT NULL DEFAULT '', participantes jsonb NOT NULL DEFAULT '[]'::jsonb, status text NOT NULL DEFAULT 'rascunho', numero_roteiro integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.sorteio_premio_programas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, premio_id uuid NOT NULL REFERENCES public.sorteio_premios(id) ON DELETE CASCADE, programa_id uuid NOT NULL REFERENCES public.programas(id) ON DELETE CASCADE, quantidade integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(premio_id,programa_id));
CREATE TABLE public.teleprompters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, estudio text NOT NULL DEFAULT '', nome text NOT NULL DEFAULT '', ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.transcricoes_streaming (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), texto_transcrito text NOT NULL, timestamp_inicio timestamptz NOT NULL DEFAULT now(), timestamp_fim timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.tv_pairing_codes (code text PRIMARY KEY, slug_user_id uuid NOT NULL, user_slug text NOT NULL, tv_session_id text NOT NULL, paired_user_id uuid, paired_email text, paired_name text, paired_avatar text, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), claimed_at timestamptz, expires_at timestamptz NOT NULL DEFAULT (now()+interval '15 minutes'));
CREATE TABLE public.tv_pairing_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug_user_id uuid, user_slug text, tv_session_id text, code text, event_type text NOT NULL, reason text, paired_user_id uuid, paired_email text, user_agent text, ip text, meta jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.vmix_switcher_categorias (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, estudio text, nome text NOT NULL DEFAULT 'Categoria', icone text, ordem integer NOT NULL DEFAULT 0, inputs jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.watch_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, channel_id uuid REFERENCES public.streaming_channels(id) ON DELETE CASCADE, channel_name text NOT NULL DEFAULT '', channel_cover_url text DEFAULT '', channel_logo_url text DEFAULT '', channel_type text NOT NULL DEFAULT 'video', watched_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.xml_upload_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, source text NOT NULL DEFAULT 'online', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.music_likes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, radio_user_id uuid, artista text NOT NULL DEFAULT '', musica text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.comercial_preroll (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, video_url text NOT NULL DEFAULT '', dias_semana text[] DEFAULT '{}', horario_inicio text NOT NULL, horario_fim text NOT NULL, priority integer NOT NULL DEFAULT 1, active boolean NOT NULL DEFAULT true, skip_enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), link_url text, media_type text, youtube_url text, data_inicial date, data_final date, nome text, views_count integer DEFAULT 0, clicks_count integer DEFAULT 0, background_url text, aspect_ratio text, video_position jsonb, is_midroll boolean DEFAULT false, placements text[] DEFAULT '{}', ads_cliente text, ads_canais text[]);
CREATE TABLE public.shopping_products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, program_id uuid REFERENCES public.programas(id) ON DELETE SET NULL, name text NOT NULL, image_url text DEFAULT '', price numeric(10,2) NOT NULL DEFAULT 0, stock integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), description text, payment_url text);
